// Package sierpinski generates Sierpinski triangles as ASCII art using
// recursive midpoint subdivision.
package sierpinski

import "strings"

// Generate returns the rows of a Sierpinski triangle.
//
// size is the number of rows (and the base width in lattice points); depth is
// the recursion depth. A depth of 0 produces a fully filled triangle. char is
// the rune used for filled points. The returned slice has exactly size rows,
// each with trailing whitespace trimmed. For size <= 0 it returns an empty
// slice.
func Generate(size, depth int, char rune) []string {
	if size <= 0 {
		return []string{}
	}

	width := 2*size - 1
	grid := make([][]rune, size)
	for r := range grid {
		grid[r] = make([]rune, width)
		for c := range grid[r] {
			grid[r][c] = ' '
		}
	}

	// The apex sits at the horizontal center so the base spans the full width.
	subdivide(grid, 0, size-1, size, depth, char)

	lines := make([]string, size)
	for r := range grid {
		lines[r] = strings.TrimRight(string(grid[r]), " ")
	}
	return lines
}

// subdivide recursively renders an upward-pointing triangle whose apex is at
// (rowTop, apexCol) and whose height is side. When depth reaches 0 (or the
// triangle shrinks to a single row) the triangle is filled solid; otherwise it
// is split into three half-size triangles with the middle left empty.
func subdivide(grid [][]rune, rowTop, apexCol, side, depth int, char rune) {
	if side <= 1 || depth <= 0 {
		fillSolid(grid, rowTop, apexCol, side, char)
		return
	}

	half := side / 2
	subdivide(grid, rowTop, apexCol, half, depth-1, char)            // top
	subdivide(grid, rowTop+half, apexCol-half, half, depth-1, char)  // bottom-left
	subdivide(grid, rowTop+half, apexCol+half, half, depth-1, char)  // bottom-right
}

// fillSolid renders a fully filled upward-pointing triangle of the given height
// with its apex at (rowTop, apexCol).
func fillSolid(grid [][]rune, rowTop, apexCol, side int, char rune) {
	for i := 0; i < side; i++ {
		for j := -i; j <= i; j += 2 {
			grid[rowTop+i][apexCol+j] = char
		}
	}
}
EOF
