// Package mandelbrot renders the Mandelbrot set as ASCII art using escape-time
// iteration.
package mandelbrot

import "strings"

// gradient maps escape speed to characters, from fastest-escaping (space) to
// in-set (@).
const gradient = " .:-=+*#%@"

// Bounds of the complex plane region rendered to the output rectangle.
const (
	realMin = -2.5
	realMax = 1.0
	imagMin = -1.0
	imagMax = 1.0
)

// Render returns the rows of the Mandelbrot set rendered to a width x height
// grid of characters. maxIter is the escape-iteration limit. If char is empty,
// points are shaded with the gradient " .:-=+*#%@" by escape speed; otherwise
// the first rune of char marks in-set points and spaces mark the rest. The
// returned slice has exactly height rows of width runes each, or is empty when
// width or height is non-positive.
func Render(width, height, maxIter int, char string) []string {
	if width <= 0 || height <= 0 {
		return []string{}
	}

	lines := make([]string, height)
	for row := 0; row < height; row++ {
		imag := mapRange(row, height, imagMin, imagMax)
		var sb strings.Builder
		sb.Grow(width)
		for col := 0; col < width; col++ {
			re := mapRange(col, width, realMin, realMax)
			iter := escapeCount(complex(re, imag), maxIter)
			sb.WriteRune(charForIter(iter, maxIter, char))
		}
		lines[row] = sb.String()
	}
	return lines
}

// mapRange maps an index in [0, n) linearly onto [min, max].
func mapRange(index, n int, min, max float64) float64 {
	if n <= 1 {
		return min
	}
	return min + (float64(index)/float64(n-1))*(max-min)
}

// escapeCount returns the number of iterations before z = z^2 + c escapes the
// circle of radius 2, capped at maxIter. A return value equal to maxIter means
// the point is considered inside the set.
func escapeCount(c complex128, maxIter int) int {
	var z complex128
	for i := 0; i < maxIter; i++ {
		z = z*z + c
		if real(z)*real(z)+imag(z)*imag(z) > 4 {
			return i
		}
	}
	return maxIter
}

// charForIter chooses the output rune for a given escape count. With a custom
// char, in-set points (iter == maxIter) use its first rune and everything else
// is a space. Otherwise the escape count is shaded along the gradient.
func charForIter(iter, maxIter int, char string) rune {
	if char != "" {
		if iter >= maxIter {
			return []rune(char)[0]
		}
		return ' '
	}

	if maxIter <= 0 {
		return rune(gradient[len(gradient)-1])
	}
	idx := iter * (len(gradient) - 1) / maxIter
	if idx >= len(gradient) {
		idx = len(gradient) - 1
	}
	return rune(gradient[idx])
}
EOF
