// binPath is the path to the freshly built fractals binary used by the
// integration tests below.
var binPath string

func TestMain(m *testing.M) {
	dir, err := os.MkdirTemp("", "fractals-it")
	if err != nil {
		panic(err)
	}
	binPath = filepath.Join(dir, "fractals")

	build := exec.Command("go", "build", "-o", binPath, ".")
	build.Stderr = os.Stderr
	if err := build.Run(); err != nil {
		os.RemoveAll(dir)
		panic("failed to build fractals binary: " + err.Error())
	}

	code := m.Run()
	os.RemoveAll(dir)
	os.Exit(code)
}

// run invokes the built binary with args, returning stdout, stderr, and exit code.
func run(t *testing.T, args ...string) (string, string, int) {
	t.Helper()
	cmd := exec.Command(binPath, args...)
	var out, errBuf bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errBuf
	err := cmd.Run()
	code := 0
	if err != nil {
		exitErr, ok := err.(*exec.ExitError)
		if !ok {
			t.Fatalf("running %v failed unexpectedly: %v", args, err)
		}
		code = exitErr.ExitCode()
	}
	return out.String(), errBuf.String(), code
}

